svg.script:
(function() {
  var root = document.getElementById('a12p9-svg');
  if (!root) return;

  function setScene(sceneNum) {
    if (sceneNum < 1) sceneNum = 1;
    if (sceneNum > 3) sceneNum = 3;
    root.setAttribute('data-scene', sceneNum.toString());
  }

  // Button Click Listeners
  var btn1 = document.getElementById('a12p9-btn-1');
  var btn2 = document.getElementById('a12p9-btn-2');
  var btn3 = document.getElementById('a12p9-btn-3');

  if (btn1) btn1.addEventListener('click', function() { setScene(1); });
  if (btn2) btn2.addEventListener('click', function() { setScene(2); });
  if (btn3) btn3.addEventListener('click', function() { setScene(3); });

  // Ring Click Listeners
  var r1 = document.getElementById('a12p9-ring-1');
  var r2 = document.getElementById('a12p9-ring-2');
  var r3 = document.getElementById('a12p9-ring-3');

  if (r1) r1.addEventListener('click', function() { setScene(1); });
  if (r2) r2.addEventListener('click', function() { setScene(2); });
  if (r3) r3.addEventListener('click', function() { setScene(3); });

  // Keyboard Navigation
  root.addEventListener('keydown', function(e) {
    var current = parseInt(root.getAttribute('data-scene') || '1', 10);
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
      setScene(current + 1);
      e.preventDefault();
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
      setScene(current - 1);
      e.preventDefault();
    } else if (e.key === '1') {
      setScene(1);
    } else if (e.key === '2') {
      setScene(2);
    } else if (e.key === '3') {
      setScene(3);
    }
  });

  // Keydown support for individual buttons
  function addKeyHandler(elem, scene) {
    if (!elem) return;
    elem.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        setScene(scene);
        e.preventDefault();
      }
    });
  }

  addKeyHandler(btn1, 1);
  addKeyHandler(btn2, 2);
  addKeyHandler(btn3, 3);
  addKeyHandler(r1, 1);
  addKeyHandler(r2, 2);
  addKeyHandler(r3, 3);
})();
